-- Kenney Furniture Kit (CC0, kenney.nl): 57 more pieces for Buy mode, each in several colour finishes.
-- Additive and idempotent. Models live in public/models/furniture/kenney/. Kenney's models come in
-- their own scale, so the renderer fits each kenney/ model to its height here (the footprint w x d
-- was worked out from the same fit). Ids start with k- so they never clash with other pieces.
--
-- Finishes: home_furniture.finishes is a list of {n: name, c: hex colour} tints; a placed piece keeps
-- the chosen colour in home_placements.finish (NULL = the model's own colours, which is what every
-- older row has).
ALTER TABLE home_furniture ADD COLUMN IF NOT EXISTS finishes JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE home_placements ADD COLUMN IF NOT EXISTS finish TEXT;

ON CONFLICT (id) DO NOTHING;
